begin;
select no_plan();
select ok(not has_function_privilege(r,'public.list_own_scoped_conversation_items_v6(uuid,text,integer,timestamptz,text,uuid)','execute'),r||' cannot read D projections') from unnest(array['anon','service_role']) r;
select ok(not has_table_privilege('authenticated','private.group_contact_read_snapshots','select'),'read tokens are not a direct table API');
insert into auth.users(id,email) select ('d1200000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'d-integrations-tap-'||n||'@planets.invalid' from generate_series(1,3) n;
insert into public.profiles(id,display_name) select id,'Fictional D integration' from auth.users where email like 'd-integrations-tap-%';
insert into private.community_groups(id,name,description,group_kind,volunteering_focus,publication_state,original_actor_id)
select ('d1210000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Fictional D group '||n,'A fictional group description for local tests.','informal',false,'published',('d1200000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,2) n;
insert into private.community_group_managers(group_id,profile_id,appointed_by_actor_id) select id,original_actor_id,original_actor_id from private.community_groups where id::text like 'd121%';
insert into private.moderation_staff_roles(profile_id,staff_role) values('d1200000-0000-4000-8000-000000000003','moderator');
create temp table d_integration_result(kind text,value jsonb); grant all on d_integration_result to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','d1200000-0000-4000-8000-000000000001',true);
insert into d_integration_result values('request',public.submit_group_contact_request('d1200000-0000-4000-8000-000000000001',gen_random_uuid(),'d1210000-0000-4000-8000-000000000001','d1210000-0000-4000-8000-000000000002','idea','Fictional idea','Fictional private initial contact.'));
select is((select count(*) from public.list_own_structured_request_message_items('d1200000-0000-4000-8000-000000000001',20)),0::bigint,'legacy requests exclude D');
select is(jsonb_array_length(public.list_own_structured_request_message_items_v2('d1200000-0000-4000-8000-000000000001',20)),1,'v2 requests include D');
select set_config('request.jwt.claim.sub','d1200000-0000-4000-8000-000000000002',true);
select public.get_own_group_contact_request('d1200000-0000-4000-8000-000000000002',(select (value->>'request_id')::uuid from d_integration_result where kind='request'));
insert into d_integration_result select 'request-report',to_jsonb(r) from public.submit_moderation_report('d1200000-0000-4000-8000-000000000002','d1230000-0000-4000-8000-000000000001','spam','Fictional explanation for private initial contact.','group_contact_request',(select (value->>'request_id')::uuid from d_integration_result where kind='request')) r;
select is((select count(*) from public.list_own_moderation_reports('d1200000-0000-4000-8000-000000000002')),0::bigint,'legacy report parser gets no new target kind');
select is((select count(*) from public.list_own_moderation_reports_v2('d1200000-0000-4000-8000-000000000002')),1::bigint,'v2 complete report scope');
select throws_ok($$select public.submit_moderation_report('d1200000-0000-4000-8000-000000000002','d1230000-0000-4000-8000-000000000001','spam','Changed report explanation.','profile','d1200000-0000-4000-8000-000000000001')$$,'PT409',null,'D report key cannot replay through a legacy target');
insert into d_integration_result values('chat',public.accept_group_contact_request('d1200000-0000-4000-8000-000000000002',gen_random_uuid(),(select (value->>'request_id')::uuid from d_integration_result where kind='request')));
select set_config('request.jwt.claim.sub','d1200000-0000-4000-8000-000000000001',true);
insert into d_integration_result values('message',public.send_group_contact_message('d1200000-0000-4000-8000-000000000001',gen_random_uuid(),(select (value->>'chat_id')::uuid from d_integration_result where kind='chat'),'Fictional human content'));
select set_config('request.jwt.claim.sub','d1200000-0000-4000-8000-000000000002',true);
select is(public.get_own_message_unread_summary('d1200000-0000-4000-8000-000000000002')->>'groups','0','legacy unread unchanged');
select is(public.get_own_message_unread_summary_v2('d1200000-0000-4000-8000-000000000002')->>'groups','1','new complete-scope unread');
select is(jsonb_array_length(public.list_own_scoped_conversation_items_v5('d1200000-0000-4000-8000-000000000002','groups',20)),0,'legacy chat rows exclude D');
select is(jsonb_array_length(public.list_own_scoped_conversation_items_v6('d1200000-0000-4000-8000-000000000002','groups',20)),1,'new Groups rows include D');
select is(jsonb_array_length(public.list_own_scoped_conversation_items_v6('d1200000-0000-4000-8000-000000000002','private',20)),0,'D never enters Private');
select set_config('request.jwt.claim.sub','d1200000-0000-4000-8000-000000000003',true);
select is(public.get_moderation_case_group_contact('d1200000-0000-4000-8000-000000000003',(select (value->>'case_id')::uuid from d_integration_result where kind='request-report'))->>'body','Fictional private initial contact.','staff exact reported evidence only');
select throws_ok($$select public.get_own_group_contact_conversation('d1200000-0000-4000-8000-000000000003',(select (value->>'chat_id')::uuid from d_integration_result where kind='chat'))$$,'42501',null,'staff role does not grant conversation');
reset role;
select throws_ok($$delete from public.profiles where id='d1200000-0000-4000-8000-000000000001'$$,'23503',null,'existing report retention gate remains unchanged for Plan 10');
select ok(not exists(select 1 from pg_constraint k join pg_class t on t.oid=k.conrelid join pg_namespace n on n.oid=t.relnamespace
  where n.nspname='private' and t.relname like 'group_contact_%' and k.contype='f' and k.confrelid in('public.profiles'::regclass,'auth.users'::regclass)),'D records add no deletion-blocking account FK');
select is((select count(*) from private.group_contact_messages where conversation_id=(select (value->>'chat_id')::uuid from d_integration_result where kind='chat')),1::bigint,'D content remains retained');
select * from finish();
rollback;
